# AI Office v2.6 Part H Final Integration Certification Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.6-part-h-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination
    if ($Parent) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath
        if ($BackupParent) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Invoke-AIOfficeExplicitMemoryCaptureForTurn.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Certify-AIOfficeV26MemoryRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Publish-AIOfficeV26Release.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeV26GitReleaseCommands.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Release-Notes.md" -Base64Content ""
$RuntimePath = ".\scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
$RuntimeText = Get-Content -LiteralPath $RuntimePath -Raw
$CaptureMarker = "Invoke-AIOfficeExplicitMemoryCaptureForTurn.ps1"
if (-not $RuntimeText.Contains($CaptureMarker)) {
  $RuntimeBackup = Join-Path $BackupDirectory "scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
  New-Item -ItemType Directory -Path (Split-Path -Parent $RuntimeBackup) -Force | Out-Null
  Copy-Item -LiteralPath $RuntimePath -Destination $RuntimeBackup -Force
  $Needle = "try {"
  $Insert = @'
try {
    # v2.6 Part H explicit durable-memory capture. Failure is non-fatal.
    $MemoryCapture = & "E:\AI\AI-Office\scripts\memory\Invoke-AIOfficeExplicitMemoryCaptureForTurn.ps1" `
        -Content $Content `
        -Scope $MemoryScope

'@
  $First = $RuntimeText.IndexOf($Needle)
  if ($First -lt 0) { throw "Could not find primary try block in conversational runtime." }
  $RuntimeText = $RuntimeText.Substring(0,$First) + $Insert + $RuntimeText.Substring($First + $Needle.Length)
  Set-Content -LiteralPath $RuntimePath -Value $RuntimeText -Encoding UTF8
  Write-Host "[PATCHED] Live explicit memory capture wired into conversational runtime." -ForegroundColor Green
} else {
  Write-Host "[PRESENT] Live explicit memory capture already wired." -ForegroundColor Green
}

$Scripts = @(
"E:\AI\AI-Office\scripts\memory\Invoke-AIOfficeExplicitMemoryCaptureForTurn.ps1",
"E:\AI\AI-Office\scripts\memory\Certify-AIOfficeV26MemoryRelease.ps1",
"E:\AI\AI-Office\scripts\memory\Publish-AIOfficeV26Release.ps1",
"E:\AI\AI-Office\scripts\memory\Get-AIOfficeV26GitReleaseCommands.ps1",
"E:\AI\AI-Office\scripts\conversational-office\Invoke-AIOfficeConversationTurn.ps1"
)
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
  if ($ParseErrors.Count -gt 0) {
    throw ("Syntax error in " + $Script + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; "))
  }
}
Write-Host ""
Write-Host "AI Office v2.6 Part H Final Integration installed successfully." -ForegroundColor Green
Write-Host "Run final certification before publishing or restarting Discord." -ForegroundColor Yellow
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan